<template><div class="auth-page"><section class="auth-card"><h1>{{ title }}</h1><p>{{ message }}</p><router-link v-if="state!=='loading'" to="/login">Go to sign in</router-link></section></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{AuthApiError,verifyEmail}from'@/api/auth';const route=useRoute(),state=ref('loading'),title=ref('Verifying your email…'),message=ref('Please wait.');onMounted(async()=>{const token=String(route.query.token||'');if(!token){state.value='error';title.value='Invalid link';message.value='This verification link is invalid.';return}try{await verifyEmail(token);state.value='success';title.value='Email verified';message.value='Your account is ready. You can now sign in.'}catch(e){state.value='error';title.value='Verification failed';message.value=e instanceof AuthApiError?e.message:'Unable to verify this email.'}})</script>
<style scoped>.auth-page{display:grid;place-items:center;min-height:60vh}.auth-card{width:min(400px,100%);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:2rem;text-align:center}</style>
